INSERT INTO `generalsettings_user` (`id`, `logo`, `light_logo`, `favicon`, `title`, `footer`, `helpline_number`, `support_email`, `created_at`, `updated_at`, `adminnumber`, `fb_link`, `linkedin_link`, `twitter_link`, `youtube_link`, `telegramlink`, `firebase_key_for_user`, `firebase_key_for_astrologer`, `insta_link`, `address`, `playstore_link`, `appstore_link`, `enquiry_email`, `about_us`, `about_us_footer`, `terms_and_condition`, `privacy_policy`, `contact_us`, `loyality_program_about`, `loyality_program_points`, `loyality_program_become_member`, `loyality_program_steps_to_earn`, `loyality_program_steps_to_redeem`, `loyality_program_points_credit`, `loyality_faq`) VALUES
(1,	'logo_astro-shop_1687776358.png',	'light_logo_logo-dark-text_1640955961.png',	'',	'Dentus',	'Dentus',	'8069160450',	'support@dentus.com',	NULL,	'2024-08-27 09:25:56',	'9538911266',	'https://www.facebook.com/',	'https://www.linkedin.com/company/',	'https://twitter.com/',	'https://youtube.com/',	'https://t.m/astrolight',	'AAAAStPR1HQ:APA91bFFAPbjmDwbpv2vyDqdGL8hC_ghSkDHFHv30cfLWvVoPnDmV5W-Gkel5uCVUH6fid5RdwJFSeGwRSRFckTK9qpZLMcMgujW_gaBoKZIa60zDPhSM-g3EJ1ofLwZS_YkWkUzWd8b',	'AAAAStPR1HQ:APA91bFFAPbjmDwbpv2vyDqdGL8hC_ghSkDHFHv30cfLWvVoPnDmV5W-Gkel5uCVUH6fid5RdwJFSeGwRSRFckTK9qpZLMcMgujW_gaBoKZIa60zDPhSM-g3EJ1ofLwZS_YkWkUzWd8b',	'https://instagram.com/dentus',	'',	'https://play.google.com/store/apps/details?id=com',	'https://play.google.com/store/apps/details?id=com',	'enquiry@dentus.com',	'<p>Welcome to <strong>DENTUS</strong>, your trusted online dental consultation platform that combines modern technology with expert dental care. Step into a world where advanced dentistry practices seamlessly merge with innovative solutions, offering you easy access to personalized dental advice and treatments from the comfort of your home.</p><p>Dentus is a brand of <strong>Dentus Healthcare Pvt. Ltd.</strong>, founded in 2023. Our parent company, <strong>Dentus Healthcare [ISO 9001:2015]</strong>, was established in 2016. Our initial mission was to provide accessible dental care and education to people from all walks of life, making quality oral healthcare services available online. Over the years, we have expanded our reach and have guided thousands of patients through various dental journeys, from preventive care to advanced treatments.</p><p>Inspired by the belief that a healthy smile is a gateway to a healthier life, Dentus combines the latest dental technologies with the convenience of online consultations. We understand the power of a confident smile, and we are here to help you achieve it with expert guidance and modern dental practices. At Dentus, we believe that every individual deserves personalized care that addresses their unique dental needs, helping them maintain oral health and wellness for years to come.</p><p>Through Dentus, you can embark on a transformative journey toward better dental health. Our team of skilled and certified dentists, led by renowned dental experts, will guide you in understanding your dental condition and suggest customized treatment plans. Whether it\'s routine checkups, cosmetic dental procedures, or emergency care, we are here to help you every step of the way.</p><p>We understand that each patient has different needs, which is why we offer personalized dental consultations. From teeth whitening and fillings to orthodontics and root canal treatments, our consultations are tailored to your specific requirements. Whether you\'re seeking clarity about dental procedures, looking for cosmetic solutions, or managing oral health concerns, Dentus provides you with expert insights and actionable advice.</p><p>In addition to our expert consultations, Dentus features a variety of resources to help you maintain your oral health. Explore our educational materials, tips on oral hygiene, and the latest updates in dental care through our app, designed to enrich your understanding of dental wellness.</p><p>We know that life is busy, so Dentus is designed to fit seamlessly into your routine. Enjoy the convenience of online consultations and easy access to expert dentists from anywhere, at any time. Whether you\'re seeking advice during a dental emergency or just want to better understand your oral health, we\'re here to help guide you through it.</p><p>Embrace the journey to a healthier smile with Dentus. Join our growing community of dental care seekers and discover the power of personalized, professional dental consultations. We believe that a healthy smile is not just about aesthetics but a reflection of your overall health and well-being. Welcome to Dentus, where advanced dental care meets modern technology.</p