DELIMITER ;;

CREATE TRIGGER `bookings_bi` BEFORE INSERT ON `bookings` FOR EACH ROW
BEGIN
    DECLARE session_id VARCHAR(20);

    SELECT MAX(CONVERT(SUBSTRING_INDEX(session_no, 'DENTUS', -1), UNSIGNED)) INTO @max_order_no FROM bookings;

    SET session_id = CONCAT('DENTUS', LPAD(IFNULL(@max_order_no + 1, 1), 6, '0'));

    SET NEW.session_no = session_id;

    
END;;

CREATE TRIGGER `bookings_biinvoice` BEFORE INSERT ON `bookings` FOR EACH ROW
BEGIN
    DECLARE new_id VARCHAR(20);

    SELECT MAX(CONVERT(SUBSTRING_INDEX(invoice_no, 'DNTS', -1), UNSIGNED)) INTO @max_invoice_no FROM bookings;

    SET new_id = CONCAT('DNTS', LPAD(IFNULL(@max_invoice_no + 1, 1), 6, '0'));

    SET NEW.invoice_no = new_id;

    
END;;

DELIMITER ;

