  `diagnosis` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `advice` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `prescription` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
